<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Create Notice - DormSync</title><style>*{box-sizing:border-box}body{background:#f7f9fc;color:#172033;font-family:Arial,sans-serif;margin:0}main{max-width:620px;margin:auto;padding:40px 24px}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:24px}label{display:block;font-weight:600;font-size:13px;margin:14px 0 6px}input,textarea,button{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}textarea{min-height:140px}button{margin-top:18px;background:#2563eb;color:#fff;border-color:#2563eb;font-weight:600}.error{color:#991b1b;font-size:13px}</style></head><body><main><section class="panel"><h1>Create system notice</h1><?php foreach($errors as $fieldErrors):foreach((array)$fieldErrors as $error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endforeach;endforeach;?><form method="post" action="/admin/notice-store"><input type="hidden" name="scope" value="system"><label for="title">Title</label><input id="title" name="title" maxlength="150" required><label for="message">Message</label><textarea id="message" name="message" required></textarea><button type="submit">Publish notice</button></form></section></main></body></html>